import{z as i,x as B,o as l,c as p,q as n,j as o,D as e,d as E,s as r,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"幻觉分类","description":"","frontmatter":{"title":"幻觉分类","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hallucination-taxonomy.md","filePath":"llm/hallucination-taxonomy.md","lastUpdated":1791413859000}'),d={name:"llm/hallucination-taxonomy.md"};function m(h,a,D,f,u,c){const t=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=n('<h1 id="幻觉分类" tabindex="-1">幻觉分类 <a class="header-anchor" href="#幻觉分类" aria-label="Permalink to &quot;幻觉分类&quot;">​</a></h1><div class="epigraph"><p>不是所有假话都是一类病。事实编造、错误引用、无根据的推理，对应不同的持有集和不同的训练补丁。</p><footer>—— 对照 Ji 等幻觉综述的分类习惯；事实轴见 [SimpleQA](/llm/simpleqa-freshqa)</footer></div><p><a href="/llm/faithful-cot">上一课</a>把「说得像推理」从「算得对」里拆开。本课把<strong>假内容</strong>再拆开：幻觉分类。主干已有诚实与引用课；缺口是产品上把一切错误叫幻觉，导致检索、拒答、解码温度被当成同一味药。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/honesty-citations">虚构引用</a> 是幻觉的一种：有来源形态、无来源事实。另一些是封闭书知识错误、过时知识、工具返回被改写、以及推理链上的非法步骤。若只用「幻觉率」一个数，RAG 系统会与纯参数模型比错对象：前者的错更常是检索未命中后的脑补，后者是记忆与校准。</p><p><span class="marginnote">术语翻译：RAG（检索增强生成）就是「答题前先去资料库翻一页，把翻到的内容贴进上下文再作答」。它的错误因此分两段——没翻到（检索未命中）和翻到了却自己脑补（生成不忠）；混进一个「幻觉率」里就治不了。</span></p><p>本课钉三类，后课弃权只处理「知道自己不知道」那一类。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三类。<strong>事实幻觉</strong>：可核验命题为假。<strong>归因幻觉</strong>：命题或许可真，但引用、页码、链接是编的。<strong>忠实性幻觉</strong>（对源文本）：摘要/RAG 中添加源里没有的约束。评测必须分列：封闭书 QA、引用可解析率、忠实度（源约束）。不要把数学算错算进事实幻觉——那是推理错误，走可验证奖励。</p><p><span class="marginnote">归因幻觉的典型样子：结论「Transformer 是 2017 年提出的」没错，配的引用却是「Vaswani et al., 2019，第 42 页」——年份页码全是编的。模型学到的是「学术论文都带引用」这个形态，而不是去核实那条引用本身。</span></p><p><span class="marginnote">「幻觉」在临床是感知，在 LLM 是生成。词已经用滥。写报告时宁可写「封闭书错误 / 归因错误 / 对源不忠」，把幻觉留作口头统称。</span></p>',11)),(l(),o(s,null,{default:e(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E9%94%99%E8%AF%AF%E7%94%9F%E6%88%90%22%5D%20--%3E%20F%5B%22%E4%BA%8B%E5%AE%9E%EF%BC%9A%E5%91%BD%E9%A2%98%E5%81%87%22%5D%0A%20%20ERR%20--%3E%20A%5B%22%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%BC%95%E7%94%A8%E5%81%87%22%5D%0A%20%20ERR%20--%3E%20S%5B%22%E5%AF%B9%E6%BA%90%E4%B8%8D%E5%BF%A0%22%5D%0A%20%20ERR%20--%3E%20R%5B%22%E6%8E%A8%E7%90%86%E9%9D%9E%E6%B3%95%E6%AD%A5%E9%AA%A4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[E("事实错误来自参数里的错误相关与过自信解码。归因错误来自「学术文风」先验：人类文本常带引用形态，语言模型会补全形态。对源不忠来自上下文与参数记忆的混合——"),A("a",{href:"/llm/long-context-vs-rag"},"长上下文是否取代 RAG"),E(" 没有取消混合，只是把源放进窗口。分类的用处是选补丁：事实走检索与校准，归因走强制引用解析，对源走抽取约束。")],-1)),a[5]||(a[5]=A("p",null,"每一类对应各自的补丁，互不通用：",-1)),(l(),o(s,null,{default:e(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22%E4%BA%8B%E5%AE%9E%E5%B9%BB%E8%A7%89%3A%20%E5%91%BD%E9%A2%98%E4%B8%BA%E5%81%87%22%5D%20--%3E%20P1%5B%22%E6%A3%80%E7%B4%A2%20%2B%20%E6%A0%A1%E5%87%86%20%2F%20%E6%8B%92%E7%AD%94%22%5D%0A%20%20A%5B%22%E5%BD%92%E5%9B%A0%E5%B9%BB%E8%A7%89%3A%20%E5%BC%95%E7%94%A8%E7%BC%96%E9%80%A0%22%5D%20--%3E%20P2%5B%22%E5%BC%BA%E5%88%B6%E5%BC%95%E7%94%A8%E5%8F%AF%E8%A7%A3%E6%9E%90%E3%80%81%E9%80%90%E6%9D%A1%E6%A0%B8%E9%AA%8C%22%5D%0A%20%20S%5B%22%E5%AF%B9%E6%BA%90%E4%B8%8D%E5%BF%A0%3A%20%E6%B7%BB%E5%8A%A0%E6%BA%90%E5%A4%96%E5%86%85%E5%AE%B9%22%5D%20--%3E%20P3%5B%22%E6%8A%BD%E5%8F%96%E5%BC%8F%E7%BA%A6%E6%9D%9F%EF%BC%8C%E5%8F%AA%E5%87%86%E6%8A%84%E6%BA%90%22%5D%0A%20%20R%5B%22%E6%8E%A8%E7%90%86%E9%9D%9E%E6%B3%95%E6%AD%A5%E9%AA%A4%22%5D%20--%3E%20P4%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%A5%96%E5%8A%B1%20%2F%20%E9%80%90%E6%AD%A5%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给越狱式「诱导编造」的提示。下一课弃权是事实轴上的动作，不是归因解析器。版权与记忆化是另一条法律/提取轴，再后一课才写。</p><p><span class="marginnote">为什么分类值得较真：把归因幻觉当事实幻觉治，会拼命加检索——可引用是模型自己编的，翻多少资料都没用。先判类、再选补丁，才不会把三个病塞给同一个温度旋钮。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>幻觉要分事实、归因、对源不忠；推理错误单列。</li><li>单指标幻觉率会让 RAG 与闭书模型比错。</li><li>补丁按类选，不共用一个温度旋钮。</li><li>出处：幻觉综述的分类习惯；SimpleQA / 引用课。</li></ul>',5))])}const g=i(d,[["render",m]]);export{_ as __pageData,g as default};
